(1325,'random\r\nrandomtext哪个职业可以治疗他们的队友？\nlink_menu=-1,icon=default.png,script=2战士/link_menu			\r\nlink_menu=1,icon=default.png僧侣/link_menu				\r\nlink_menu=-1,icon=default.png,script=2游侠/link_menu\r\n/randomtext\r\nrandomtext科纳斯瓦斯监狱的最终Boss叫什么名字？\nlink_menu=-1,icon=default.png,script=2无声者金度拉/link_menu			\r\nlink_menu=-1,icon=default.png,script=2哈什拉德/link_menu				\r\nlink_menu=1,icon=default.png科斯莫/link_menu\r\n/randomtext\r\nrandomtext僧侣不能使用下列哪种武器？ \r\nlink_menu=-1,icon=default.png,script=2法杖/link_menu			\r\nlink_menu=1,icon=default.png盾/link_menu				\r\nlink_menu=-1,icon=default.png,script=2拳套/link_menu\r\n/randomtext\r\n/random',0,1341,3606,1332,0,0,0,0,0,0,0,0),
(1326,'random\r\nrandomtext每日任务每天什么时候刷新？\nlink_menu=-1,icon=default.png,script=2北京时间15:00/link_menu			\r\nlink_menu=1,icon=default.png北京时间11:00/link_menu				\r\nlink_menu=-1,icon=default.png,script=2北京时间20:00/link_menu\r\n/randomtext\r\nrandomtext下列哪种活动会奖励经验值？\nlink_menu=-1,icon=default.png,script=2出售物品/link_menu			\r\nlink_menu=-1,icon=default.png,script=2从拍卖行购买物品/link_menu		\r\nlink_menu=1,icon=default.png完成一个任务/link_menu\r\n/randomtext\r\nrandomtext你可以消耗下列那件物品来回复生命值？ \r\nlink_menu=-1,icon=default.png,script=2强效法力药水/link_menu			\r\nlink_menu=1,icon=default.png烤蜥蜴/link_menu				\r\nlink_menu=-1,icon=default.png,script=2敏捷卷轴 I/link_menu\r\n/randomtext\r\n/random',0,1343,3606,1333,0,0,0,0,0,0,0,0),
(1327,'random\r\nrandomtext哪个首领会掉落史诗物品克莫德之爪？\nlink_menu=1,icon=default.png克莫德/link_menu			\r\nlink_menu=-1,icon=default.png,script=2哈什拉德/link_menu				\r\nlink_menu=-1,icon=default.png,script=2阿尔-拉吉尔/link_menu\r\n/randomtext\r\nrandomtext田园牧歌森林区域最大的城市是什么？\nlink_menu=-1,icon=default.png,script=2格林守望/link_menu			\r\nlink_menu=-1,icon=default.png,script=2格林山/link_menu				\r\nlink_menu=1,icon=default.png格林蒙特/link_menu\r\n/randomtext\r\nrandomtext哪个职业可以给他们的武器附毒？\nlink_menu=-1,icon=default.png,script=2战士/link_menu			\r\nlink_menu=-1,icon=default.png,script=2僧侣/link_menu				\r\nlink_menu=1,icon=default.png游侠/link_menu\r\n/randomtext\r\n/random',0,1345,3606,1334,0,0,0,0,0,0,0,0),
